const raw = JSON.stringify($json.raw || {});
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  return [{ json: { drift_detected: true, severity: 'error', reason: 'invalid_json', discord_message: `⚠️ **Model canary failed** — could not parse OpenClaw JSON at ${new Date().toISOString()}` } }];
}

const text = (parsed?.result?.payloads?.[0]?.text || '').trim();
const meta = parsed?.result?.meta?.agentMeta || {};
const runtimeModel = [meta.provider, meta.model].filter(Boolean).join('/');
const promptText = `You are running a daily model canary for KAOS.
Return plain text only.

Follow this exact structure and headings:
SUMMARY:
- One sentence on what changed in AI agent operations this week.

RISKS:
- Two bullets, each 8-16 words.

NEXT_STEPS:
- Three numbered steps for KAOS operations this week.

VERDICT:
stable | watch | drifted

Rules:
- Do not add any extra headings.
- Mention Discord once.
- Mention Mission Control once.
- Keep total length between 120 and 220 words.
`;
const promptVersion = 'v1';

function simpleHash(input) {
  let hash = 2166136261;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
  }
  return ('0000000' + (hash >>> 0).toString(16)).slice(-8);
}

function normalize(value) {
  return (value || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
}

function similarity(a, b) {
  const aSet = new Set(normalize(a).split(' ').filter(Boolean));
  const bSet = new Set(normalize(b).split(' ').filter(Boolean));
  if (!aSet.size && !bSet.size) return 1;
  let intersection = 0;
  for (const token of aSet) if (bSet.has(token)) intersection++;
  const union = new Set([...aSet, ...bSet]).size;
  return union ? intersection / union : 1;
}

const lines = text.split(String.fromCharCode(10)).map(line => line.split(String.fromCharCode(13)).join('').trim()).filter(Boolean);
const metrics = {
  chars: text.length,
  words: text ? text.split(/\s+/).filter(Boolean).length : 0,
  lines: lines.length,
  has_summary: /^SUMMARY:/m.test(text),
  has_risks: /^RISKS:/m.test(text),
  has_next_steps: /^NEXT_STEPS:/m.test(text),
  has_verdict: /^VERDICT:/m.test(text),
  mentions_discord: /discord/i.test(text),
  mentions_mission_control: /mission control/i.test(text),
  risk_bullets: (text.match(/^- /gm) || []).length,
  numbered_steps: (text.match(/^\d+\. /gm) || []).length,
  prompt_hash: simpleHash(promptText),
  output_hash: simpleHash(text),
};

const requiredMissing = [];
for (const [key, label] of [
  ['has_summary', 'SUMMARY'],
  ['has_risks', 'RISKS'],
  ['has_next_steps', 'NEXT_STEPS'],
  ['has_verdict', 'VERDICT'],
  ['mentions_discord', 'Discord mention'],
  ['mentions_mission_control', 'Mission Control mention'],
]) {
  if (!metrics[key]) requiredMissing.push(label);
}
if (metrics.risk_bullets < 2) requiredMissing.push('2 risk bullets');
if (metrics.numbered_steps < 3) requiredMissing.push('3 numbered steps');

const staticData = $getWorkflowStaticData('global');
const stateKey = 'kaos_model_canary_v1';
const previous = staticData[stateKey] || null;
const current = {
  timestamp: new Date().toISOString(),
  runtime_model: runtimeModel,
  prompt_version: promptVersion,
  prompt_hash: metrics.prompt_hash,
  output_text: text,
  metrics,
};

let driftReasons = [];
let comparison = null;
if (previous) {
  const similarityScore = similarity(previous.output_text || '', text);
  const charDeltaRatio = previous.metrics?.chars ? Math.abs(metrics.chars - previous.metrics.chars) / previous.metrics.chars : 0;
  const lineDeltaRatio = previous.metrics?.lines ? Math.abs(metrics.lines - previous.metrics.lines) / previous.metrics.lines : 0;
  comparison = {
    previous_model: previous.runtime_model || '',
    similarity: Number(similarityScore.toFixed(3)),
    char_delta_ratio: Number(charDeltaRatio.toFixed(3)),
    line_delta_ratio: Number(lineDeltaRatio.toFixed(3)),
  };
  if (previous.runtime_model && runtimeModel && previous.runtime_model !== runtimeModel) driftReasons.push(`runtime model changed: ${previous.runtime_model} → ${runtimeModel}`);
  if (requiredMissing.length) driftReasons.push(`required elements missing: ${requiredMissing.join(', ')}`);
  if (similarityScore < 0.55) driftReasons.push(`low output similarity (${comparison.similarity})`);
  if (charDeltaRatio > 0.4) driftReasons.push(`length shifted sharply (${Math.round(charDeltaRatio * 100)}%)`);
  if (lineDeltaRatio > 0.5) driftReasons.push(`line count shifted sharply (${Math.round(lineDeltaRatio * 100)}%)`);
} else if (requiredMissing.length) {
  driftReasons.push(`baseline output malformed: ${requiredMissing.join(', ')}`);
}

staticData[stateKey] = current;

const driftDetected = driftReasons.length > 0;
const message = driftDetected
  ? `🧪 **KAOS model canary drift detected**
• Model: \`${runtimeModel || 'unknown'}\`
• Prompt: ${promptVersion} / ${metrics.prompt_hash}
• Reasons: ${driftReasons.join('; ')}
• Metrics: ${metrics.words} words, ${metrics.lines} lines, similarity ${comparison ? comparison.similarity : 'n/a'}
• Time: ${current.timestamp}`
  : `Model canary OK — ${runtimeModel || 'unknown'} — ${current.timestamp}`;

return [{ json: {
  drift_detected: driftDetected,
  baseline_run: !previous,
  runtime_model: runtimeModel,
  prompt_version: promptVersion,
  prompt_hash: metrics.prompt_hash,
  output_text: text,
  metrics,
  comparison,
  drift_reasons: driftReasons,
  discord_message: message,
} }];
